-- ----------------------------
-- Table structure for admission_method
-- ----------------------------
DROP TABLE IF EXISTS `admission_method`;
CREATE TABLE `admission_method`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `admission_id` int NULL DEFAULT NULL COMMENT '记录ID',
  `patient_id` int NULL DEFAULT NULL COMMENT '关联急救患者ID',
  `method_type` tinyint NULL DEFAULT NULL COMMENT '来院方式（1呼叫120/2转院/3自行来院/4院内发病）',
  `ambulance_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '出车单位：120救护车、本院救护车、外院救护车',
  `call_time` datetime NULL DEFAULT NULL COMMENT '呼救时间',
  `hospital_arrival_time` datetime NULL DEFAULT NULL COMMENT '到达医院大门时间（1、2、3适用）',
  `is_transfer_high_hospital` tinyint(1) NULL DEFAULT 0 COMMENT '是否直接转上级医院',
  `first_medical_contact_time` datetime NULL DEFAULT NULL COMMENT '首次医疗接触时间',
  `first_diagnosis_time` datetime NULL DEFAULT NULL COMMENT '首诊医师接诊时间（1、3适用）',
  `medical_staff` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '医护人员（1、2、3、4适用）',
  `transfer_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '转院类型（2适用）：网络医院、其他医疗机构',
  `transfer_hospital_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '转院医院名称（2适用）',
  `transfer_hospital_in_time` datetime NULL DEFAULT NULL COMMENT '转出医院入门时间（2适用）',
  `decision_transfer_time` datetime NULL DEFAULT NULL COMMENT '决定转院时间（2适用）',
  `transfer_hospital_out_time` datetime NULL DEFAULT NULL COMMENT '转出医院出门时间（2适用）',
  `in_hospital_contact_time` datetime NULL DEFAULT NULL COMMENT '在转出医院出门时间（2适用）',
  `onset_department` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发病科室（4适用）',
  `bed_medical_contact_time` datetime NULL DEFAULT NULL COMMENT '床位医生接触时间（4适用）',
  `leave_department_time` datetime NULL DEFAULT NULL COMMENT '离开科室时间（4适用）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '患者来院方式记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of admission_method
-- ----------------------------

