-- Table structure for pms_heart_diagnosis
-- ----------------------------
DROP TABLE IF EXISTS `pms_heart_diagnosis`;
CREATE TABLE `pms_heart_diagnosis`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增Id',
  `patient_id` int NOT NULL COMMENT '患者Id',
  `is_cardiology_consultation` tinyint(1) NULL DEFAULT 0 COMMENT '是否进行心内科会诊',
  `consultation_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '会诊类型（现场会诊、远程会诊）',
  `notification_consultation_time` datetime NULL DEFAULT NULL COMMENT '通知会诊时间',
  `consultation_time` datetime NULL DEFAULT NULL COMMENT '实际会诊时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 68 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '心内科会诊信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pms_heart_diagnosis
-- ----------------------------

-- ----------------------------
-- Table structure for pms_hospital
-- ----------------------------
DROP TABLE IF EXISTS `pms_hospital`;
CREATE TABLE `pms_hospital`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `hospital` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '记录医院',
  `type` int NULL DEFAULT NULL COMMENT '医院类型',
  `is_treatment_unit` tinyint(1) NULL DEFAULT 0 COMMENT '是否救治单元',
  `is_enabled` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '医院信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pms_hospital
-- ----------------------------

-- ----------------------------
-- Table structure for pms_hospital_department
-- ----------------------------
DROP TABLE IF EXISTS `pms_hospital_department`;
CREATE TABLE `pms_hospital_department`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '记录科室',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '医院科室表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pms_hospital_department
-- ----------------------------

-- ----------------------------
-- Table structure for pms_laboratory_tests
-- ----------------------------
DROP TABLE IF EXISTS `pms_laboratory_tests`;
CREATE TABLE `pms_laboratory_tests`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `troponin_i` decimal(10, 2) NULL DEFAULT NULL,
  `ck_mb` int NULL DEFAULT NULL,
  `white_blood_cells` decimal(10, 2) NULL DEFAULT NULL,
  `neutrophil_percentage` int NULL DEFAULT NULL,
  `coagulation_function` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `check_time` datetime NULL DEFAULT NULL,
  `patient_id` int NULL DEFAULT NULL COMMENT '患者Id',
  `is_report_troponin` tinyint(1) NULL DEFAULT NULL COMMENT '是否根据实际情况多次上报肌钙蛋白',
  `first_troponin_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '首次肌钙蛋白类型（Tnt或Tnl）',
  `troponin_value` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '肌钙蛋白单位（ng/ml、ug/L 、ng/L、pg/ml、mg/L等）',
  `troponin_result` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '肌钙蛋白结果（阴性、阳性）',
  `blood_draw_completion_time` datetime NULL DEFAULT NULL COMMENT '抽血完成时间',
  `report_obtain_time` datetime NULL DEFAULT NULL COMMENT '获得报告时间',
  `is_serum_creatinine` tinyint(1) NULL DEFAULT NULL COMMENT '是否检测血清肌酐',
  `serum_creatinine_value` decimal(10, 2) NULL DEFAULT NULL COMMENT '血清肌酐数值，单位umol/L',
  `is_d_dimer` tinyint(1) NULL DEFAULT NULL COMMENT '是否检测D - 二聚体',
  `d_dimer_value` decimal(10, 2) NULL DEFAULT NULL COMMENT 'D - 二聚体数值，单位ug/L',
  `is_bnp` tinyint(1) NULL DEFAULT NULL COMMENT '是否检测BNP',
  `bnp_value` decimal(10, 2) NULL DEFAULT NULL COMMENT 'BNP数值，单位pg/ml',
  `is_nt_pro_bnp` tinyint(1) NULL DEFAULT NULL COMMENT '是否检测NT - proBNP',
  `nt_pro_bnp_value` decimal(10, 2) NULL DEFAULT NULL COMMENT 'NT - proBNP数值，单位pg/ml',
  `is_myo` tinyint(1) NULL DEFAULT NULL COMMENT '是否检测Myo',
  `myo_value` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Myo数值，单位ng/ml、ug/L',
  `is_ckmb` tinyint(1) NULL DEFAULT NULL COMMENT '是否检测CKMB',
  `ckmb_value` decimal(10, 2) NULL DEFAULT NULL COMMENT 'CKMB数值，单位ng/ml、ug/L 、U/L',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 137 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of pms_laboratory_tests
-- ----------------------------

-- ----------------------------
-- Table structure for pms_lung
-- ----------------------------
DROP TABLE IF EXISTS `pms_lung`;
CREATE TABLE `pms_lung`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增Id',
  `patient_id` int NOT NULL COMMENT '患者Id',
  `initial_diagnosis_time` datetime NULL DEFAULT NULL COMMENT '初步诊断时间',
  `imaging_examination_pe` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '影像学检查类型，取值为“急诊CT”“未做”',
  `notify_ct_room_time_pe` datetime NULL DEFAULT NULL COMMENT '通知CT室时间（若选择急诊CT）',
  `ct_room_ready_time_pe` datetime NULL DEFAULT NULL COMMENT 'CT室完成准备时间（若选择急诊CT）',
  `ct_scan_start_time_pe` datetime NULL DEFAULT NULL COMMENT 'CT扫描开始时间（若选择急诊CT）',
  `ct_report_time_pe` datetime NULL DEFAULT NULL COMMENT 'CT报告时间（若选择急诊CT）',
  `risk_stratification_pe` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '危险分层，取值为“高危”“中危”“低危”',
  `anticoagulation_start_time_pe` datetime NULL DEFAULT NULL COMMENT '开始抗凝治疗时间',
  `thrombolysis_screening_pe` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '溶栓筛查结果，取值为“合适”“不合适”“未筛查”',
  `is_thrombolysis_treatment_pe` tinyint(1) NULL DEFAULT NULL COMMENT '是否有溶栓治疗，“是”为True，“否”为False',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '肺栓塞影像学检查与治疗信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pms_lung
-- ----------------------------

-- ----------------------------
-- Table structure for pms_nstemi
-- ----------------------------
DROP TABLE IF EXISTS `pms_nstemi`;
CREATE TABLE `pms_nstemi`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增Id',
  `patient_id` int NOT NULL COMMENT '患者Id',
  `initial_diagnosis_time` datetime NULL DEFAULT NULL COMMENT '初步诊断时间',
  `cardiac_function_grade_nstemi` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '心功能分级',
  `is_bypass_emergency_nstemi` tinyint(1) NULL DEFAULT NULL COMMENT '是否绕行急诊',
  `is_bypass_ccu_nstemi` tinyint(1) NULL DEFAULT NULL COMMENT '是否绕行CCU',
  `is_antiplatelet_therapy_nstemi` tinyint(1) NULL DEFAULT NULL COMMENT '是否进行抗血小板治疗',
  `aspirin_dosage_nstemi` decimal(10, 2) NULL DEFAULT NULL COMMENT '阿司匹林剂量（mg）',
  `aspirin_time_nstemi` datetime NULL DEFAULT NULL COMMENT '阿司匹林用药时间',
  `clopidogrel_dosage_nstemi` decimal(10, 2) NULL DEFAULT NULL COMMENT '氯吡格雷剂量（mg）',
  `clopidogrel_time_nstemi` datetime NULL DEFAULT NULL COMMENT '氯吡格雷用药时间',
  `prasugrel_dosage_nstemi` decimal(10, 2) NULL DEFAULT NULL COMMENT '替格瑞洛剂量（mg）',
  `prasugrel_time_nstemi` datetime NULL DEFAULT NULL COMMENT '替格瑞洛用药时间',
  `is_anticoagulation_nstemi` tinyint(1) NULL DEFAULT NULL COMMENT '是否进行抗凝治疗',
  `anticoagulant_drug_nstemi` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '抗凝药物种类',
  `anticoagulant_dose_nstemi` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '抗凝药物剂量',
  `anticoagulation_time_nstemi` datetime NULL DEFAULT NULL COMMENT '抗凝药物使用时间',
  `is_statin_therapy_nstemi` tinyint(1) NULL DEFAULT NULL COMMENT '是否进行他汀治疗',
  `is_beta_blocker_nstemi` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用β受体阻滞剂',
  `is_cardiac_arrest_after_onset` tinyint(1) NULL DEFAULT NULL COMMENT '发病后曾出现心脏骤停',
  `is_ecg_st_segment_change` tinyint(1) NULL DEFAULT NULL COMMENT '心电图ST段改变',
  `is_cardiac_necrosis_marker_elevation` tinyint(1) NULL DEFAULT NULL COMMENT '心肌坏死标志物升高',
  `is_refractory_angina_and_st_segment_change` tinyint(1) NULL DEFAULT NULL COMMENT '急性心衰伴难治性心绞痛和ST段改变',
  `is_life_threatening_arrhythmia_or_cardiac_arrest` tinyint(1) NULL DEFAULT NULL COMMENT '危及生命的心律失常或心脏骤停',
  `is_cardiogenic_shock_or_hemodynamic_instability` tinyint(1) NULL DEFAULT NULL COMMENT '心源性休克或血流动力学不稳定',
  `is_mechanical_complication_of_myocardial_infarction` tinyint(1) NULL DEFAULT NULL COMMENT '心肌梗死机械性并发症',
  `is_dynamic_st_segment_change` tinyint(1) NULL DEFAULT NULL COMMENT '再发ST-动态演变',
  `grace_score_nstemi` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Grace评分',
  `grace_risk_stratification_nstemi` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Grace危险分层',
  `is_repeated_risk_stratification` tinyint(1) NULL DEFAULT NULL COMMENT '是否再次危险分层',
  `repeated_risk_stratification_result_nstemi` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '再次危险分层结果',
  `repeated_risk_stratification_time_nstemi` datetime NULL DEFAULT NULL COMMENT '再次危险分层时间',
  `treatment_strategy_nstemi` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '处理策略',
  `invasive_strategy_nstemi` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '侵入性策略',
  `emergency_intervention_doctor_nstemi` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '决定紧急介入治疗的医生姓名',
  `emergency_intervention_decision_time_nstemi` datetime NULL DEFAULT NULL COMMENT '决定介入手术时间',
  `emergency_intervention_cath_lab_start_time_nstemi` datetime NULL DEFAULT NULL COMMENT '启动导管室时间',
  `emergency_intervention_informed_consent_start_time_nstemi` datetime NULL DEFAULT NULL COMMENT '开始知情同意时间',
  `emergency_intervention_informed_consent_sign_time_nstemi` datetime NULL DEFAULT NULL COMMENT '签署知情同意时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'NSTEMI患者详细信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pms_nstemi
-- ----------------------------

-- ----------------------------
-- Table structure for pms_nstemi_or_ua
-- ----------------------------
DROP TABLE IF EXISTS `pms_nstemi_or_ua`;
CREATE TABLE `pms_nstemi_or_ua`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增Id',
  `patient_id` int NOT NULL COMMENT '患者Id',
  `catheter_lab_activation_time` datetime NULL DEFAULT NULL COMMENT '导管室激活时间',
  `patient_arrival_time` datetime NULL DEFAULT NULL COMMENT '患者到达导管室时间',
  `interventionist` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '介入医师姓名',
  `start_puncture_time` datetime NULL DEFAULT NULL COMMENT '开始穿刺时间',
  `angiography_start_time` datetime NULL DEFAULT NULL COMMENT '造影开始时间',
  `anticoagulation_drug_time` datetime NULL DEFAULT NULL COMMENT '抗凝给药时间',
  `anticoagulation_drug` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '抗凝药物种类',
  `anticoagulation_drug_dose` decimal(10, 2) NULL DEFAULT NULL COMMENT '抗凝药物剂量',
  `anticoagulation_drug_unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '抗凝药物剂量单位',
  `surgery_end_time` datetime NULL DEFAULT NULL COMMENT '手术结束时间',
  `access_route` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '入路',
  `coronary_angiography_site` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '冠脉造影部位',
  `stenosis_degree` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '狭窄程度',
  `timi_flow_during_angiography` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '造影时TIMI血流',
  `is_in_stent_thrombosis` tinyint(1) NULL DEFAULT NULL COMMENT '是否有支架内血栓',
  `is_bifurcation_lesion` tinyint(1) NULL DEFAULT NULL COMMENT '是否为分叉病变',
  `is_cto` tinyint(1) NULL DEFAULT NULL COMMENT '是否为CTO',
  `is_calcified_lesion` tinyint(1) NULL DEFAULT NULL COMMENT '是否为钙化病变',
  `culprit_lesion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '罪犯病变',
  `pci_procedure` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'PCI术中处理',
  `wire_passage_time` datetime NULL DEFAULT NULL COMMENT '导丝通过时间',
  `number_of_stents_implanted` int NULL DEFAULT NULL COMMENT '植入支架个数',
  `stent_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支架种类',
  `intravascular_imaging` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '腔内影像',
  `functional_detection` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '功能检测',
  `functional_detection_value` decimal(10, 2) NULL DEFAULT NULL COMMENT '功能检测数值',
  `is_iabp_used` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用IABP',
  `is_temporary_pacemaker_used` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用临时起搏器',
  `is_ecmo_used` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用ECMO',
  `is_left_heart_assist_device_used` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用左心辅助装置',
  `intraoperative_complications` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '术中并发症',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'NSTEMI/UA 导管室手术数据表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pms_nstemi_or_ua
-- ----------------------------

-- ----------------------------
-- Table structure for pms_other_heart
-- ----------------------------
DROP TABLE IF EXISTS `pms_other_heart`;
CREATE TABLE `pms_other_heart`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增Id',
  `patient_id` int NOT NULL COMMENT '患者Id',
  `initial_diagnosis_time` datetime NULL DEFAULT NULL COMMENT '初步诊断时间',
  `other_non_cardiac_chest_pain_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '其它非心源性胸痛类型，取值为“呼吸系统病”“消化系统病”等',
  `patient_status_other` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '处理措施',
  `treatment_measure_other` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '其它非心源性胸痛信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pms_other_heart
-- ----------------------------

-- ----------------------------
-- Table structure for pms_out_hospital_info
-- ----------------------------
DROP TABLE IF EXISTS `pms_out_hospital_info`;
CREATE TABLE `pms_out_hospital_info`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增Id',
  `patient_id` int NULL DEFAULT NULL COMMENT '患者Id',
  `hospitalization_days` decimal(5, 2) NULL DEFAULT NULL COMMENT '住院天数，单位：天',
  `total_cost` decimal(12, 2) NULL DEFAULT NULL COMMENT '总费用，单位：元',
  `patient_outcome` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '患者转归',
  `discharge_time` datetime NULL DEFAULT NULL COMMENT '出院时间（若转归为出院）',
  `treatment_outcome` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '治疗结果（若转归为出院）',
  `is_carry_medication_after_discharge` tinyint(1) NULL DEFAULT NULL COMMENT '出院是否带药（若转归为出院）',
  `antithrombotic_drug_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '抗血小板药物名称',
  `antithrombotic_drug_dose` decimal(10, 2) NULL DEFAULT NULL COMMENT '抗血小板药物剂量，mg',
  `is_aceiarb` tinyint(1) NULL DEFAULT NULL COMMENT '是否带ACEI/ARB药物',
  `aceiarb_drug_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'ACEI/ARB药物名称',
  `aceiarb_drug_dose` decimal(10, 2) NULL DEFAULT NULL COMMENT 'ACEI/ARB药物剂量，mg',
  `is_lipid_lowering_drug` tinyint(1) NULL DEFAULT NULL COMMENT '是否带调脂药物',
  `lipid_lowering_drug_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '调脂药物名称',
  `lipid_lowering_drug_dose` decimal(10, 2) NULL DEFAULT NULL COMMENT '调脂药物剂量，mg',
  `is_beta_blocker` tinyint(1) NULL DEFAULT NULL COMMENT '是否带β受体阻滞剂',
  `beta_blocker_drug_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'β受体阻滞剂药物名称',
  `beta_blocker_drug_dose` decimal(10, 2) NULL DEFAULT NULL COMMENT 'β受体阻滞剂药物剂量，mg',
  `leave_hospital_time` datetime NULL DEFAULT NULL COMMENT '离开本院大门时间（若转送其他医院）',
  `is_network_hospital` tinyint(1) NULL DEFAULT NULL COMMENT '是否转往网络医院',
  `transfer_hospital_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '转往医院名称',
  `is_transfer_pci` tinyint(1) NULL DEFAULT NULL COMMENT '是否转运PCI',
  `is_direct_to_catheter_lab` tinyint(1) NULL DEFAULT NULL COMMENT '是否直达导管室',
  `actual_intervention_start_time` datetime NULL DEFAULT NULL COMMENT '实际介入手术开始时间',
  `is_tele_ecg_transmission` tinyint(1) NULL DEFAULT NULL COMMENT '是否远程心电图传输',
  `ecg_transmission_time` datetime NULL DEFAULT NULL COMMENT '传输心电图时间',
  `ecg_transmission_method` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '心电图传输方式',
  `patient_condition_description_transfer_hospital` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '转院患者情况说明',
  `transfer_department_time` datetime NULL DEFAULT NULL COMMENT '转科时间',
  `transfer_department_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '转科原因描述',
  `accepting_department` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '接诊科室',
  `patient_condition_description_transfer_department` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '转科患者情况说明',
  `death_time` datetime NULL DEFAULT NULL COMMENT '死亡时间',
  `is_cardiac_cause_of_death` tinyint(1) NULL DEFAULT NULL COMMENT '是否为心源性死亡',
  `patient_condition_description_death` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '死亡患者情况说明',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '出院信息表' ROW_FORMAT = Dynamic;

