-- Records of pms_out_hospital_info
-- ----------------------------

-- ----------------------------
-- Table structure for pms_outhospital_diagnosis
-- ----------------------------
DROP TABLE IF EXISTS `pms_outhospital_diagnosis`;
CREATE TABLE `pms_outhospital_diagnosis`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增Id',
  `patient_id` int NOT NULL COMMENT '患者Id',
  `diagnosis` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '诊断结果',
  `diagnosis_confirmation_time` datetime NULL DEFAULT NULL COMMENT '确诊时间',
  `is_new_onset_heart_failure_in_hospital` tinyint(1) NULL DEFAULT NULL COMMENT '院内是否新发心力衰竭',
  `complications` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '合并症',
  `is_hypertension` tinyint(1) NULL DEFAULT NULL COMMENT '是否有高血压',
  `is_hyperlipidemia` tinyint(1) NULL DEFAULT NULL COMMENT '是否有高脂血症',
  `is_diabetes` tinyint(1) NULL DEFAULT NULL COMMENT '是否有糖尿病',
  `is_smoking` tinyint(1) NULL DEFAULT NULL COMMENT '是否吸烟',
  `is_obesity` tinyint(1) NULL DEFAULT NULL COMMENT '是否肥胖',
  `is_early_onset_cvd_family_history` tinyint(1) NULL DEFAULT NULL COMMENT '是否有早发CVD家族史',
  `is_coronary_heart_disease` tinyint(1) NULL DEFAULT NULL COMMENT '是否有冠心病',
  `is_revascularization_history` tinyint(1) NULL DEFAULT NULL COMMENT '是否有血运重建史',
  `is_atrial_fibrillation` tinyint(1) NULL DEFAULT NULL COMMENT '是否有心房颤动',
  `atrial_fibrillation_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '心房颤动分型',
  `is_chronic_heart_failure` tinyint(1) NULL DEFAULT NULL COMMENT '是否有慢性心力衰竭',
  `nyha_classification` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'NYHA分级',
  `is_valvular_heart_disease` tinyint(1) NULL DEFAULT NULL COMMENT '是否有心脏瓣膜病',
  `is_cerebrovascular_disease` tinyint(1) NULL DEFAULT NULL COMMENT '是否有脑血管疾病',
  `cerebrovascular_disease_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '脑血管疾病描述',
  `is_peripheral_arterial_disease` tinyint(1) NULL DEFAULT NULL COMMENT '是否有外周动脉疾病',
  `is_aortic_aneurysm` tinyint(1) NULL DEFAULT NULL COMMENT '是否有主动脉瘤',
  `is_copd` tinyint(1) NULL DEFAULT NULL COMMENT '是否有COPD',
  `is_chronic_kidney_disease` tinyint(1) NULL DEFAULT NULL COMMENT '是否有慢性肾病',
  `is_anemia` tinyint(1) NULL DEFAULT NULL COMMENT '是否有贫血',
  `is_peptic_ulcer` tinyint(1) NULL DEFAULT NULL COMMENT '是否有消化性溃疡',
  `is_thyroid_dysfunction` tinyint(1) NULL DEFAULT NULL COMMENT '是否有甲状腺功能异常',
  `is_72h_troponin_checked` tinyint(1) NULL DEFAULT NULL COMMENT '是否检查72h内肌钙蛋白',
  `troponin_type_72h` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '72h内肌钙蛋白类型',
  `troponin_max_value_72h` decimal(10, 4) NULL DEFAULT NULL COMMENT '72h内肌钙蛋白最高值',
  `is_natriuretic_peptide_checked` tinyint(1) NULL DEFAULT NULL COMMENT '是否检查脑钠肽',
  `natriuretic_peptide_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '脑钠肽类型',
  `natriuretic_peptide_max_value` decimal(10, 4) NULL DEFAULT NULL COMMENT '脑钠肽最高值',
  `is_total_cholesterol_checked` tinyint(1) NULL DEFAULT NULL COMMENT '是否检查总胆固醇(TC)',
  `total_cholesterol_value` decimal(10, 4) NULL DEFAULT NULL COMMENT '总胆固醇数值',
  `is_triglyceride_checked` tinyint(1) NULL DEFAULT NULL COMMENT '是否检查甘油三酯(TG)',
  `triglyceride_value` decimal(10, 4) NULL DEFAULT NULL COMMENT '甘油三酯数值',
  `is_hdl_checked` tinyint(1) NULL DEFAULT NULL COMMENT '是否检查高密度脂蛋白(HDL - C)',
  `hdl_value` decimal(10, 4) NULL DEFAULT NULL COMMENT '高密度脂蛋白数值',
  `is_ldl_checked` tinyint(1) NULL DEFAULT NULL COMMENT '是否检查低密度脂蛋白(LDL - C)',
  `dl_value` decimal(10, 4) NULL DEFAULT NULL COMMENT '低密度脂蛋白数值',
  `is_echocardiogram_checked` tinyint(1) NULL DEFAULT NULL COMMENT '是否检查超声心动图',
  `is_ventricular_aneurysm` tinyint(1) NULL DEFAULT NULL COMMENT '超声心动图检查是否有室壁瘤',
  `is_regional_wall_motion_abnormality` tinyint(1) NULL DEFAULT NULL COMMENT '是否有局部室壁活动异常',
  `non_acs_cardiogenic_chest_pain_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '非ACS心源性胸痛类型',
  `other_non_cardiac_chest_pain_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '其他非心源性胸痛类型',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '出院诊断信息表' ROW_FORMAT = Dynamic;

