-- ----------------------------
-- Table structure for pms_ua
-- ----------------------------
DROP TABLE IF EXISTS `pms_ua`;
CREATE TABLE `pms_ua`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增Id',
  `patient_id` int NOT NULL COMMENT '患者Id',
  `initial_diagnosis_time` datetime NULL DEFAULT NULL COMMENT '初步诊断时间',
  `cardiac_function_grade_ua` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '心功能分级',
  `is_bypass_emergency_ua` tinyint(1) NULL DEFAULT NULL COMMENT '是否绕行急诊',
  `is_bypass_ccu_ua` tinyint(1) NULL DEFAULT NULL COMMENT '是否绕行CCU',
  `is_antiplatelet_therapy_ua` tinyint(1) NULL DEFAULT NULL COMMENT '是否进行抗血小板治疗',
  `aspirin_dosage_ua` double NULL DEFAULT NULL COMMENT '阿司匹林剂量',
  `aspirin_time_ua` datetime NULL DEFAULT NULL COMMENT '阿司匹林用药时间',
  `clopidogrel_dosage_ua` double NULL DEFAULT NULL COMMENT '氯吡格雷剂量',
  `clopidogrel_time_ua` datetime NULL DEFAULT NULL COMMENT '氯吡格雷用药时间',
  `prasugrel_dosage_ua` double NULL DEFAULT NULL COMMENT '替格瑞洛剂量',
  `prasugrel_time_ua` datetime NULL DEFAULT NULL COMMENT '替格瑞洛用药时间',
  `is_anticoagulation_ua` tinyint(1) NULL DEFAULT NULL COMMENT '是否进行抗凝治疗',
  `anticoagulant_drug_ua` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '抗凝药物种类',
  `anticoagulant_dose_ua` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '抗凝药物剂量',
  `anticoagulation_time_ua` datetime NULL DEFAULT NULL COMMENT '抗凝药物使用时间',
  `is_statin_therapy_ua` tinyint(1) NULL DEFAULT NULL COMMENT '是否进行他汀治疗',
  `is_beta_blocker_ua` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用β受体阻滞剂',
  `is_cardiac_arrest_after_onset_ua` tinyint(1) NULL DEFAULT NULL COMMENT '发病后曾出现心脏骤停',
  `is_ecg_st_segment_change_ua` tinyint(1) NULL DEFAULT NULL COMMENT '心电图ST段改变',
  `is_cardiac_necrosis_marker_elevation_ua` tinyint(1) NULL DEFAULT NULL COMMENT '心肌坏死标志物升高',
  `is_refractory_angina_and_st_segment_change_ua` tinyint(1) NULL DEFAULT NULL COMMENT '难治性心绞痛和ST段改变',
  `is_life_threatening_arrhythmia_or_cardiac_arrest_ua` tinyint(1) NULL DEFAULT NULL COMMENT '危及生命的心律失常或心脏骤停',
  `is_cardiogenic_shock_or_hemodynamic_instability_ua` tinyint(1) NULL DEFAULT NULL COMMENT '心源性休克或血流动力学不稳定',
  `is_mechanical_complication_of_myocardial_infarction_ua` tinyint(1) NULL DEFAULT NULL COMMENT '心梗机械性并发症',
  `is_dynamic_st_segment_change_ua` tinyint(1) NULL DEFAULT NULL COMMENT '再发ST动态演变',
  `grace_score_ua` double NULL DEFAULT NULL COMMENT 'Grace评分',
  `grace_risk_stratification_ua` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Grace危险分层',
  `is_repeated_risk_stratification_ua` tinyint(1) NULL DEFAULT NULL COMMENT '是否再次危险分层',
  `repeated_risk_stratification_result_ua` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '再次危险分层结果',
  `repeated_risk_stratification_time_ua` datetime NULL DEFAULT NULL COMMENT '再次危险分层时间',
  `treatment_strategy_ua` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '处理策略',
  `invasive_strategy_ua` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '侵入性策略',
  `emergency_intervention_doctor_ua` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '紧急介入治疗决定医生',
  `emergency_intervention_decision_time_ua` datetime NULL DEFAULT NULL COMMENT '决定介入时间',
  `emergency_intervention_cath_lab_start_time_ua` datetime NULL DEFAULT NULL COMMENT '启动导管室时间',
  `emergency_intervention_informed_consent_start_time_ua` datetime NULL DEFAULT NULL COMMENT '开始知情同意时间',
  `emergency_intervention_informed_consent_sign_time_ua` datetime NULL DEFAULT NULL COMMENT '签署知情同意时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '不稳定型心绞痛患者诊疗信息表' ROW_FORMAT = Dynamic;

